Here is the source code:
<source_code>
import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        long n = s.nextLong();
        double p = s.nextDouble();

        solve(n, p);
    }

    public static void solve(long n, double p) {
        // We need to find minimum number of maps to study such that
        // probability of playing a studied map is at least p

        // Total number of ways to choose 3 maps from n: C(n,3)
        long totalWays = n * (n - 1) * (n - 2) / 6;

        for (long studied = 0; studied <= n; studied++) {
            long notStudied = n - studied;

            // Count favorable outcomes where at least one of the 3 selected maps is studied
            // and it's the one that gets selected (considering the selection process)

            // Case 1: 0 studied maps in the 3 selected
            // Both players discard the 3 unstudied maps, system randomly picks one of 3 unstudied maps
            // Probability of playing studied map = 0
            long case0 = notStudied * (notStudied - 1) * (notStudied - 2) / 6;

            // Case 2: 1 studied map in the 3 selected
            // The studied map will be picked by at least one player (since opponents pick randomly)
            // If both players discard the unstudied maps, the studied map remains
            // If one player discards studied, the other must discard one unstudied, so studied and one unstudied remain
            // System randomly picks from remaining maps
            // Actually, let's think more carefully:
            // With 1 studied (S) and 2 unstudied (U1, U2):
            // Each player picks one to discard
            // Possible discard pairs: (S,S), (S,U1), (S,U2), (U1,S), (U1,U1), (U1,U2), (U2,S), (U2,U1), (U2,U2)
            // But since each player picks from {S, U1, U2}, and they pick independently:
            // If both pick S: remaining {U1, U2}, system picks randomly -> 0 chance of S
            // If player1 picks S, player2 picks U1: remaining {U2}, system picks U2 -> 0 chance
            // If player1 picks S, player2 picks U2: remaining {U1}, system picks U1 -> 0 chance
            // If player1 picks U1, player2 picks S: remaining {U2}, system picks U2 -> 0 chance
            // If player1 picks U1, player2 picks U1: remaining {S, U2}, system picks randomly -> 1/2 chance
            // If player1 picks U1, player2 picks U2: remaining {S}, system picks S -> 1 chance
            // If player1 picks U2, player2 picks S: remaining {U1}, system picks U1 -> 0 chance
            // If player1 picks U2, player2 picks U1: remaining {S}, system picks S -> 1 chance
            // If player1 picks U2, player2 picks U2: remaining {S, U1}, system picks randomly -> 1/2 chance

            // Count scenarios where studied map is selected:
            // (U1,U1): 1 way for player1, 1 way for player2 -> 1 scenario, prob 1/2
            // (U1,U2): 1 way for player1, 1 way for player2 -> 1 scenario, prob 1
            // (U2,U1): 1 way for player1, 1 way for player2 -> 1 scenario, prob 1
            // (U2,U2): 1 way for player1, 1 way for player2 -> 1 scenario, prob 1/2
            // Total favorable probability contribution: (1/2 + 1 + 1 + 1/2) / 9 = 3/9 = 1/3

            // Actually, let's reconsider: each player has 3 choices, so 9 equally likely outcomes
            // Favorable outcomes: 6 out of 9 give probability 1/3

            // Case 3: 2 studied maps in the 3 selected
            // With 2 studied (S1, S2) and 1 unstudied (U):
            // Each player picks one to discard
            // Favorable scenarios: when at least one studied map survives and is selected
            // This is complex, let's use a different approach

            // Simpler approach: compute expected number of studied maps in final game
            // The game map is selected from maps not discarded by either player

            // For a specific studied map to be selected:
            // It must be among the 3 shown maps
            // Neither player discards it
            // It gets randomly selected from remaining maps

            // Probability a specific studied map is selected:
            // P(it's in the 3 shown) * P(both players don't discard it | it's in the 3 shown) * P(it gets selected | it's not discarded)

            // P(it's in the 3 shown) = C(n-1, 2) / C(n, 3) = 3/n

            // Given it's in the 3 shown, there are 2 other maps. Each player randomly picks one of 3 to discard.
            // P(both players don't discard it) = (2/3) * (2/3) = 4/9

            // Given it's not discarded, how many maps remain?
            // If both players discard different maps (not the studied one), 1 map remains -> probability 1
            // If both players discard the same map (not the studied one), 2 maps remain -> probability 1/2

            // P(both discard same map | studied not discarded) = P(both discard same of the 2 others) = 2/9 / (4/9) = 1/2
            // Actually: each player picks from 3 maps. P(both pick same specific map) = 1/9, so P(both pick same) = 2/9
            // P(both discard different) = 1 - 2/9 = 7/9
            // But we're conditioning on neither discarding the studied map, so they pick from the other 2 maps
            // P(both pick same) = 2/4 = 1/2 (each has 2 choices, 2 same out of 4)
            // P(both pick different) = 1/2

            // So P(selected | studied in show, not discarded) = (1/2)*1 + (1/2)*(1/2) = 3/4

            // Overall: (3/n) * (4/9) * (3/4) = (3/n) * (1/3) = 1/n

            // So each studied map has probability 1/n of being selected
            // Expected number of studied maps selected = studied * (1/n)

            // But we want P(played map is studied) = expected number of studied maps selected / expected total maps selected
            // Since exactly 1 map is always selected: P = studied * (1/n)

            // Wait, that can't be right because the selection process is more complex

            // Let's go back to the original approach but fix the calculation

            // The correct approach is to count all possible scenarios
            // Total ways to choose 3 maps: C(n,3)
            // For each combination of 3 maps, count the probability that a studied map is selected

            // For 0 studied maps: prob = 0
            // For 1 studied map: as calculated above, 1/3 chance
            // For 2 studied maps: let's recalculate
            // For 3 studied maps: prob = 1 (since all remaining maps are studied)

            long case1 = studied * notStudied * (notStudied - 1) / 2;
            long case2 = studied * (studied - 1) * notStudied / 2;
            long case3 = studied * (studied - 1) * (studied - 2) / 6;

            // Probability contribution:
            // case0: 0
            // case1: case1 * (1.0/3.0)
            // case2: case2 * (2.0/3.0)  [need to verify]
            // case3: case3 * 1.0

            // For case2 (2 studied, 1 unstudied):
            // Maps: S1, S2, U
            // Each player picks one to discard
            // Total 9 equally likely outcomes
            // S1 survives if not discarded by either: P = (2/3)*(2/3) = 4/9
            // S2 survives if not discarded by either: P = 4/9
            // U survives if not discarded by either: P = 4/9
            // But exactly 1 or 2 maps survive depending on discards

            // If both discard same map: 1 map remains (the one not discarded)
            // If both discard different maps: 2 maps remain
            // P(both discard same) = 3/9 = 1/3 (both discard S1, both discard S2, or both discard U)
            // P(both discard different) = 6/9 = 2/3

            // If both discard same:
            // - Both discard S1: S2 and U remain? No, if both discard S1, then S1 is discarded, S2 and U remain
            // Wait, if both players discard the same map, that map is discarded, and the other 2 remain
            // So 2 maps remain, system picks randomly -> 1/2 chance for each

            // If both discard different:
            // - Player1 discards S1, Player2 discards S2: U remains
            // - Player1 discards S1, Player2 discards U: S2 remains
            // - Player1 discards S2, Player2 discards S1: U remains
            // - Player1 discards S2, Player2 discards U: S1 remains
            // - Player1 discards U, Player2 discards S1: S2 remains
            // - Player1 discards U, Player2 discards S2: S1 remains
            // So in all these cases, exactly 1 map remains, and it's always a studied map (S1 or S2)
            // So probability = 1

            // If both discard same:
            // - Both discard S1: S2 and U remain, probability of S = 1/2
            // - Both discard S2: S1 and U remain, probability of S = 1/2
            // - Both discard U: S1 and S2 remain, probability of S = 1

            // So overall for case2:
            // P(both discard S1) = 1/9, contribution = 1/2
            // P(both discard S2) = 1/9, contribution = 1/2
            // P(both discard U) = 1/9, contribution = 1
            // P(both discard different) = 6/9, contribution = 1
            // Total = (1/9)*(1/2) + (1/9)*(1/2) + (1/9)*1 + (6/9)*1 = 1/18 + 1/18 + 1/9 + 2/3 = 1/9 + 1/9 + 6/9 = 8/9

            // Hmm, that seems too high. Let me recount.

            // Actually, for case2 (2 studied, 1 unstudied), the probability that a studied map is selected should be:
            // Total favorable outcomes / total outcomes

            // Let's enumerate all 9 outcomes:
            // (S1,S1): discard S1 twice, remaining {S2, U}, P(S) = 1/2
            // (S1,S2): discard S1 and S2, remaining {U}, P(S) = 0
            // (S1,U): discard S1 and U, remaining {S2}, P(S) = 1
            // (S2,S1): discard S2 and S1, remaining {U}, P(S) = 0
            // (S2,S2): discard S2 twice, remaining {S1, U}, P(S) = 1/2
            // (S2,U): discard S2 and U, remaining {S1}, P(S) = 1
            // (U,S1): discard U and S1, remaining {S2}, P(S) = 1
            // (U,S2): discard U and S2, remaining {S1}, P(S) = 1
            // (U,U): discard U twice, remaining {S1, S2}, P(S) = 1

            // Favorable: cases 3, 6, 7, 8, 9 have P(S)=1, cases 1 and 5 have P(S)=1/2, cases 2 and 4 have P(S)=0
            // Total probability = (1/9)*(1/2 + 0 + 1 + 0 + 1/2 + 1 + 1 + 1 + 1) = (1/9)*(6) = 2/3

            // So case2 contributes 2/3

            // For case3 (3 studied): all maps are studied, so P = 1

            double prob = (case1 * 1.0 / 3.0 + case2 * 2.0 / 3.0 + case3 * 1.0) / totalWays;

            if (prob >= p) {
                System.out.println(studied);
                return;
            }
        }

        System.out.println(n);
    }
}
</source_code>
